function audit(setCookie) {
  const parts = setCookie.split(';').map((s) => s.trim());
  const lower = parts.map((p) => p.toLowerCase());
  const issues = [];

  if (!lower.some((p) => p === 'httponly')) issues.push('缺 HttpOnly（XSS 可通过 document.cookie 窃取）');
  if (!lower.some((p) => p === 'secure')) issues.push('缺 Secure（明文链路可被中间人窃听）');

  const sameSitePart = parts.find((p) => p.toLowerCase().startsWith('samesite'));
  if (!sameSitePart) issues.push('缺 SameSite（跨站请求会自动携带，存在 CSRF 风险）');

  return { name: parts[0].split('=')[0], sameSite: sameSitePart || '(未设置)', issues };
}

const CASES = [
  'sessionId=abc123; HttpOnly; Secure; SameSite=Lax; Max-Age=3600',
  'token=xyz789; Path=/',
  'theme=dark; Max-Age=604800',
];

for (const c of CASES) {
  const a = audit(c);
  console.log('Set-Cookie: ' + c);
  console.log('  Cookie 名 : ' + a.name);
  console.log('  SameSite  : ' + a.sameSite);
  console.log('  安全问题  : ' + (a.issues.length ? a.issues.join('；') : '无（三项安全属性齐备）'));
  console.log('');
}

console.log('三个属性各对应一类攻击：HttpOnly 防 XSS 窃取、Secure 防明文窃听、SameSite 防 CSRF。');
console.log('注意：SameSite=None 时必须同时加 Secure，否则现代浏览器会直接丢弃该 Cookie。');
